// The workspace runner: what the hub needs to start, find and stop a project's workspace. The hub only ever talks to
// this interface; the process runner (tests, trusted accounts) and the container runner (Task 3) launch workspaces
// behind it, and ManagedRunner gives both the same lifecycle: start on demand, idle stop, one restart, a cap.

export type WorkspaceState = "stopped" | "starting" | "running" | "failed"

export interface WorkspaceSpec {
  /** The workspace id, generated by the hub (the project id). */
  id: string
  /** The user the workspace belongs to. */
  userId: string
  /** The project folder, the workspace's only writable place. */
  projectDir: string
  /** The path the Studio is served under, such as /p/<project id>. */
  basePath: string
}

/** Where a running workspace listens, on the private interface: origins, such as http://127.0.0.1:41234. */
export interface WorkspaceAddress {
  studio: string
  mcp: string
}

export interface WorkspaceRunner {
  /** The running workspace's address, starting it first when needed. Counts as use for the idle timer. */
  ensure(spec: WorkspaceSpec): Promise<WorkspaceAddress>
  /** Marks a proxied request in flight: the workspace is not idle until the returned release is called. */
  hold(id: string): () => void
  stop(id: string): Promise<void>
  state(id: string): WorkspaceState
  /** Workspaces starting or running now. */
  running(): number
  stopAll(): Promise<void>
}

/** A launched workspace, as a launcher hands it over. */
export interface Launched {
  address: WorkspaceAddress
  /** Settles when the workspace has ended, for whatever reason. */
  exited: Promise<void>
  /** Ends it and waits until it has. */
  stop(): Promise<void>
}

export type Launcher = (spec: WorkspaceSpec) => Promise<Launched>

/** Refused because the most workspaces the server runs at once are already running. */
export class RunnerFullError extends Error {
  constructor(max: number) {
    super(`The service is busy: ${max} workspaces are already running, the most it runs at once. Try again in a few minutes.`)
  }
}

/** Refused because the workspace could not be started. The message never carries the launcher's own error. */
export class WorkspaceStartError extends Error {
  constructor() {
    super("The workspace could not be started. Try again in a minute.")
  }
}

export const DEFAULT_IDLE_MS = 15 * 60_000
export const DEFAULT_MAX_RUNNING = 20

export interface ManagedRunnerOptions {
  launch: Launcher
  /** Stop a workspace this long after its last proxied request ended; default 15 minutes. */
  idleMs?: number
  /** Workspaces starting or running at once; default 20. */
  maxRunning?: number
  /** Where launch failures and crashes are reported (server side only); default stderr. */
  log?: (line: string) => void
}

interface Entry {
  spec: WorkspaceSpec
  state: WorkspaceState
  launched?: Launched
  starting?: Promise<WorkspaceAddress>
  holds: number
  idle?: NodeJS.Timeout
  restarted: boolean
  stopping: boolean
}

/** The lifecycle every runner shares, over a launcher that starts one workspace. */
export class ManagedRunner implements WorkspaceRunner {
  private readonly entries = new Map<string, Entry>()
  private readonly idleMs: number
  private readonly maxRunning: number
  private readonly log: (line: string) => void

  constructor(private readonly options: ManagedRunnerOptions) {
    this.idleMs = options.idleMs ?? DEFAULT_IDLE_MS
    this.maxRunning = options.maxRunning ?? DEFAULT_MAX_RUNNING
    this.log = options.log ?? ((line) => process.stderr.write(`${line}\n`))
  }

  state(id: string): WorkspaceState {
    return this.entries.get(id)?.state ?? "stopped"
  }

  running(): number {
    let count = 0
    for (const entry of this.entries.values()) if (entry.state === "starting" || entry.state === "running") count += 1
    return count
  }

  async ensure(spec: WorkspaceSpec): Promise<WorkspaceAddress> {
    const known = this.entries.get(spec.id)
    if (known && (known.spec.userId !== spec.userId || known.spec.projectDir !== spec.projectDir || known.spec.basePath !== spec.basePath)) {
      throw new Error("A workspace id was reused for another project")
    }
    if (known?.state === "running" && known.launched) {
      this.armIdle(known)
      return known.launched.address
    }
    if (known?.state === "starting" && known.starting) return known.starting
    if (this.running() >= this.maxRunning) throw new RunnerFullError(this.maxRunning)
    const entry: Entry = { spec, state: "starting", holds: 0, restarted: false, stopping: false }
    this.entries.set(spec.id, entry)
    return this.start(entry)
  }

  hold(id: string): () => void {
    const entry = this.entries.get(id)
    if (!entry) return () => undefined
    entry.holds += 1
    clearTimeout(entry.idle)
    let released = false
    return () => {
      if (released) return
      released = true
      entry.holds -= 1
      this.armIdle(entry)
    }
  }

  async stop(id: string): Promise<void> {
    const entry = this.entries.get(id)
    if (!entry) return
    entry.stopping = true
    clearTimeout(entry.idle)
    if (entry.starting) await entry.starting.catch(() => undefined)
    await entry.launched?.stop().catch((error: unknown) => this.log(`workspace ${id}: stopping failed: ${(error as Error).message}`))
    if (this.entries.get(id) === entry) this.entries.delete(id)
  }

  async stopAll(): Promise<void> {
    await Promise.all([...this.entries.keys()].map((id) => this.stop(id)))
  }

  private start(entry: Entry): Promise<WorkspaceAddress> {
    entry.state = "starting"
    const starting = this.options.launch(entry.spec).then(
      (launched) => {
        entry.launched = launched
        entry.starting = undefined
        if (entry.stopping) {
          void launched.stop()
          throw new WorkspaceStartError()
        }
        entry.state = "running"
        void launched.exited.then(() => this.exited(entry, launched))
        this.armIdle(entry)
        return launched.address
      },
      (error: unknown) => {
        entry.starting = undefined
        entry.state = "failed"
        this.log(`workspace ${entry.spec.id}: start failed: ${(error as Error).message}`)
        throw new WorkspaceStartError()
      },
    )
    entry.starting = starting
    // A caller that stops waiting must not leave an unhandled rejection behind.
    starting.catch(() => undefined)
    return starting
  }

  /** A workspace ended without being asked to: restart it once, then call it failed. */
  private exited(entry: Entry, launched: Launched): void {
    if (entry.stopping || entry.launched !== launched || this.entries.get(entry.spec.id) !== entry) return
    clearTimeout(entry.idle)
    entry.launched = undefined
    if (entry.restarted) {
      entry.state = "failed"
      this.log(`workspace ${entry.spec.id}: ended again after its restart; marked failed`)
      return
    }
    entry.restarted = true
    this.log(`workspace ${entry.spec.id}: ended unexpectedly; restarting it once`)
    this.start(entry).catch(() => undefined)
  }

  private armIdle(entry: Entry): void {
    clearTimeout(entry.idle)
    if (entry.holds > 0 || entry.state !== "running") return
    entry.idle = setTimeout(() => void this.stop(entry.spec.id), this.idleMs)
    entry.idle.unref()
  }
}
